		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})

	// ServeMux treats any empty path segment (the doubled slash in
	// /v1/documents//..., /v1/devices//sessions or
	// /v1/sessions//documents/...) as an unclean path and answers with a 307
	// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
	// error for an empty identifier, so intercept those paths before the mux
	// sees them. A trailing slash empties the final id of the device/session
	// routes and is rejected there for the same reason; the document routes
	// keep their pre-existing ServeMux behavior.
	return emptyIDGuard(mux)
}

// emptyIDGuard rejects requests carrying an empty path identifier with a 400
// JSON error instead of letting ServeMux emit its HTML redirect or a
// plain-text 404.
//
// The document family keeps its original rule (an empty documentID, i.e. the
// prefix /v1/documents//); other odd paths there retain their old response so
// the pre-existing surface is unchanged. The new device/session families are
// stricter: any doubled slash (an empty deviceId, sessionId or documentId
// segment) or a trailing slash (an empty final id) is a 400 JSON error.
func emptyIDGuard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := r.URL.Path

		documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
		newFamilySegmentEmpty := false
		if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
			newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
		}

		if documentSegmentEmpty || newFamilySegmentEmpty || malformedNewDocumentPath(p) || malformedSubscribePath(p) || malformedSessionCRDTPath(p) || malformedCRDTPath(p) || malformedSnapshotPath(p) {
			writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
			return
		}
		next.ServeHTTP(w, r)
	})
}

// malformedNewDocumentPath reports whether p targets one of the new
// long-poll/replay endpoints but is not that endpoint's exact location: a
// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
// segment in a position short of the registered shape. ServeMux would answer
// those with a 301 redirect or a plain-text 404/405; the new endpoints promise
// a JSON error and never a redirect, so every such path is a malformed 400.
//
// Keywords are matched only past the documentID position, so documents that
// happen to be named "poll" or "replay" keep their ordinary merge/snapshot/
// changes routes.
func malformedNewDocumentPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")

	// Poll endpoint: "poll" must be exactly the third segment, after a
	// non-empty documentID and "changes".
	for i, seg := range segs {
		if seg == "poll" && i > 0 {
			return !(len(segs) == 3 && segs[0] != "" && segs[1] == "changes")
		}
	}
	// Replay endpoint: "replay" must be exactly the second segment, after a
	// non-empty documentID.
	for i, seg := range segs {
		if seg == "replay" && i > 0 {
			return !(len(segs) == 2 && segs[0] != "")
		}
	}
	return false
}

// malformedSubscribePath reports whether p targets the WebSocket subscription
// endpoint but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe): a
// missing "documents"/"changes" segment, an extra segment, or a "subscribe"
// segment short of the registered shape. ServeMux would answer those with a
// plain-text 404/405; every failure of this endpoint must be a JSON 400
// instead. Empty segments are already rejected by the guard itself.
//
// "subscribe" is treated as the endpoint keyword only in the endpoint's
// terminal segment position (the fifth segment, index 4); a session or
// document identifier literally named "subscribe" occupies an identifier
// position (index 0 or 2) and is therefore left to the ordinary
// changes/subscribe routes like any other id.
func malformedSubscribePath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "subscribe" there is not the changes-subscribe
	// keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "subscribe" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "subscribe" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly
		// "subscribe" with the documents/changes scaffolding around it, and no
		// segment may follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
			segs[0] != "" &&
			segs[1] == "documents" &&
			segs[2] != "" &&
			segs[3] == "changes" {
			return false
		}
		return true
	}
	return false
}

// malformedSessionCRDTPath reports whether p targets the session-scoped CRDT
// namespace but is not at one of its two exact locations:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
//
// a missing "state"/"subscribe" segment, an extra segment, or a "crdt" segment
// in the keyword position (immediately past the document identifier) short of
// one of the registered shapes. ServeMux would answer those with a
// plain-text 404/405; every failure of these endpoints must be a JSON 400
// instead. Empty segments are already rejected by the guard itself.
//
// "crdt" is treated as the endpoint keyword only in the fourth segment (index
// 3, right after the document identifier); a session or document identifier
// literally named "crdt" occupies an identifier position (index 0 or 2) and
// keeps its ordinary routes.
func malformedSessionCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "crdt" {
		return false
	}
	// Keyword position reached. The state read is exactly
	// {sessionId}/documents/{documentId}/crdt/state; the subscription adds
	// one trailing "subscribe" segment.
	validState := len(segs) == 5 &&
		segs[0] != "" &&
		segs[2] != "" &&
		segs[4] == "state"
	validSubscribe := len(segs) == 6 &&
		segs[0] != "" &&
		segs[2] != "" &&
		segs[4] == "state" &&
		segs[5] == "subscribe"
	return !(validState || validSubscribe)
}

// Handler exposes the HTTP surface over a private in-memory store. Use
// NewHandler with a durable store for real deployments.
func Handler() http.Handler {
	s, err := app.Open("")
	if err != nil {
		log.Fatalf("open in-memory app: %v", err)
	}
	return NewHandler(s)
}

// decodeJSONBody enforces the strict POST contract shared by every JSON
// endpoint: Content-Type must be application/json, the body is capped at
// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
// may follow it. Any violation writes a 400 JSON error and returns false; the
// caller returns immediately, so no handler reaches the store with malformed
// input and rejected requests write nothing.
func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return false
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(dst); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return false
	}
	// Reject trailing data after the JSON value.
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return false
	}
	return true
}

func handleRegisterDevice(s *app.App, w http.ResponseWriter, r *http.Request) {
	var req deviceRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	created, err := s.RegisterDevice(req.DeviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to register device")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
}

func handleCreateSession(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty

	var req sessionRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.SessionID == "" {
		writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
		return
	}

	created, err := s.CreateSession(deviceID, req.SessionID)
	if err != nil {
		var conflict *store.ErrSessionConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
		default:
			writeError(w, http.StatusInternalServerError, "failed to create session")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
}

func handleDeleteSession(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")   // route pattern + guard guarantee non-empty
	sessionID := r.PathValue("sessionId") // route pattern + guard guarantee non-empty

	if err := s.DeleteSession(deviceID, sessionID); err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to delete session")
		return
	}

	writeJSON(w, http.StatusOK, map[string]bool{"deleted": true})
}

func handlePostChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req postRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	// Reject trailing data after the JSON object.
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if len(req.Changes) == 0 {
		writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
		return
	}

	changes := make([]events.Change, len(req.Changes))
	seen := make(map[string]struct{}, len(req.Changes))
	for i, c := range req.Changes {
		if c.ID == "" {
			writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
			return
		}
		if len(c.Payload) == 0 {
			writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
			return
		}
		if _, dup := seen[c.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
			return
		}
		seen[c.ID] = struct{}{}
		changes[i] = events.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
	}

	results, err := s.PostChanges(documentID, changes)
	if err != nil {
		var conflict *events.ErrConflict
		if errors.As(err, &conflict) {
			writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to commit changes")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

func handleMergeChange(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req mergeRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	// baseCursor must be present and a non-negative integer (no fractions,
	// strings, booleans or null).
	if len(req.BaseCursor) == 0 {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	if req.Change == nil {
		writeError(w, http.StatusBadRequest, "change must be an object")
		return
	}
	if req.Change.ID == "" {
		writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
		return
	}
	if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
		writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
		return
	}

	result, err := s.MergeChange(documentID, baseCursor, events.Change{
		ID:       req.Change.ID,
		DeviceID: req.DeviceID,
		Payload:  req.Change.Payload,
	})
	if err != nil {
		var conflict *events.ErrConflict
		switch {
		case errors.Is(err, events.ErrStaleCursor):
			writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to merge change")
			return
		}
	}

	writeJSON(w, http.StatusOK, result)
}

func handlePostSnapshot(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req snapshotPostRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	cursor, ok := parseNonNegativeInt(req.Cursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return
	}
	if len(req.State) == 0 {
		writeError(w, http.StatusBadRequest, "state is required")
		return
	}

	created, err := s.PutSnapshot(documentID, cursor, req.State)
	if err != nil {
		var conflict *events.ErrSnapshotConflict
		switch {
		case errors.Is(err, events.ErrSnapshotBase):
			writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "snapshot already exists with a different state")
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to store snapshot")
			return
		}
	}

	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
}

func handleGetSnapshot(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	cursor, ok := parseCursorPath(r.PathValue("cursor"))
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return
	}

	state, err := s.GetSnapshot(documentID, cursor)
	if err != nil {
		if errors.Is(err, events.ErrSnapshotNotFound) {
			writeError(w, http.StatusNotFound, "snapshot not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load snapshot")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
}

func handleRestore(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
	var req restoreRequest
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
		return
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
		return
	}

	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.ChangeID == "" {
		writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
		return
	}
	// snapshotCursor must be present and a positive integer (no fractions,
	// strings, booleans, null or zero).
	if len(req.SnapshotCursor) == 0 {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}
	snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}

	result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
	if err != nil {
		var conflict *events.ErrRestoreConflict
		switch {
		case errors.Is(err, events.ErrSnapshotNotFound):
			writeError(w, http.StatusNotFound, "snapshot not found")
			return
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
			return
		default:
			writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
			return
		}
	}

	writeJSON(w, http.StatusOK, result)
}

// handleSetPermission grants or revokes a registered device's access to one
// document. Devices start authorized, so the first revoke is the first write;
// repeating the current state is idempotent (changed=false). A rejected
// request (bad content type, malformed JSON, trailing content, empty or
// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
// unregistered device is a 404 JSON error.
func handleSetPermission(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern guarantees non-empty

	var req permissionRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	var authorized bool
	switch req.Action {
	case "grant":
		authorized = true
	case "revoke":
		authorized = false
	default:
		writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
		return
	}

	changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
	if err != nil {
		if errors.Is(err, store.ErrDeviceNotFound) {
			writeError(w, http.StatusNotFound, "device not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to update permission")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"deviceId":   req.DeviceID,
		"authorized": authorized,
		"changed":    changed,
	})
}

// parseCursorPath reports whether raw is a decimal non-negative integer and
// returns its value. Signs, fractions and other adornments are rejected.
func parseCursorPath(raw string) (int64, bool) {
	if raw == "" {
		return 0, false
	}
	for _, c := range raw {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
	var n int64
	if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
		return 0, false
	}
	// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
	// require the literal to contain no fraction or exponent.
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "" || trimmed[0] == '-' {
		return 0, false
	}
	for _, c := range trimmed {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	return n, true
}

// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
// strings, booleans, null and negative numbers are rejected.
func parsePositiveInt(raw json.RawMessage) (int64, bool) {
	n, ok := parseNonNegativeInt(raw)
	if !ok || n < 1 {
		return 0, false
	}
	return n, true
}

// isJSONObject reports whether raw decodes to a JSON object (not null, an
// array or a scalar).
func isJSONObject(raw json.RawMessage) bool {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil || m == nil {
		return false
	}
	return true
}

func handleListChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID")

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}

	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list changes")
		return
	}

	writeChangesPage(w, changes, nextCursor)
}

// handleSessionChanges is the session-scoped view of the existing change log:
// both path identifiers must be non-empty (the empty-segment guard rejects
// those before routing) and the session must currently exist, after which the
// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
// the session's device has been revoked permission for the document, which is
// a 403 JSON error with no changes or nextCursor. Revocation only gates this
// read; the change log itself is untouched.
func handleSessionChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed query parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the snapshot GET ordering.
	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list changes")
		return
	}

	writeChangesPage(w, changes, nextCursor)
}

// parseChangesQuery parses the shared after/limit pagination parameters,
// writing the documented 400 on an illegal value. It is shared by the
// document-scoped and session-scoped change listings so their query semantics
// cannot drift apart.
func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
	q := r.URL.Query()

	after = 0
	if raw := q.Get("after"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
			return 0, 0, false
		}
		after = v
	}

	limit = defaultListLimit
	if raw := q.Get("limit"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 1 || v > maxListLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
			return 0, 0, false
		}
		limit = v
	}

	return after, limit, true
}

// writeChangesPage renders a change listing page in the shared response shape.
func writeChangesPage(w http.ResponseWriter, changes []events.ListedChange, nextCursor int64) {
	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
	})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

// handlePollChanges is the long-polling entry over the change log.
//
// Query params share the existing change-read constraints: after is a
// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
// is 0..30000 (default 0). Rows already past after return immediately; a known
// document caught up to after parks until the first new commit or the wait
// deadline; an unknown document returns an empty page with cursor 0 at once.
// The response shape is the ordinary page plus a timedOut flag; a deadline
// expiry echoes the caller's cursor and never advances it. A client
// disconnect simply stops the wait and writes nothing.
func handlePollChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	var waitMs int64
	if raw := q.Get("waitMs"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 || v > maxPollWaitMillis {
			writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
			return
		}
		waitMs = v
	}

	changes, nextCursor, timedOut, err := s.WaitForChanges(
		r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
	)
	switch {
	case errors.Is(err, events.ErrStoreClosing):
		writeError(w, http.StatusServiceUnavailable, "service is shutting down")
		return
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		// The client went away (or, with waitMs bounded, its deadline lapsed
		// at the transport): nothing more to write and nothing was stored.
		return
	case err != nil:
		writeError(w, http.StatusInternalServerError, "failed to poll changes")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
		"timedOut":   timedOut,
	})
}

// handleReplay retries an offline batch against the existing change log. The
// request and per-element semantics mirror POST .../changes — strict
// application/json body, non-empty ids, no in-batch duplicates, idempotent only
// when deviceId and decoded payload match, otherwise 409 reporting the
// conflicting id — with the registration/permission layer enforced first:
// 404 for an unregistered device and 403 for a revoked one, neither exposing
// change content. The whole batch commits in one serialized transaction that
// shares the document's contiguous cursor space with ordinary commits.
func handleReplay(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req replayRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Operations == nil {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}
	if len(req.Operations) == 0 {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}

	changes := make([]events.Change, len(req.Operations))
	seen := make(map[string]struct{}, len(req.Operations))
	for i, op := range req.Operations {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
			return
		}
		if len(op.Payload) == 0 {
			writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
			return
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
			return
		}
		seen[op.ID] = struct{}{}
		changes[i] = events.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
	}

	results, err := s.ReplayChanges(documentID, changes)
	if err != nil {
		var conflict *events.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeJSON(w, http.StatusConflict, map[string]string{
				"error":      "operation id already exists with different deviceId or payload",
				"conflictId": conflict.ID,
			})
		default:
			writeError(w, http.StatusInternalServerError, "failed to replay operations")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// Package store is the durable kernel shared by the internal services: it
// owns the SQLite database handle and the registration layer (devices and
// sessions) plus resumable attachments.
//
// The business services layered on top of the kernel — the change event log,
// the permission ledger and the CRDT state — live in their own packages and
// cooperate only through their internal interfaces. They all share this one
// handle: it opens a single pooled connection with immediate write
// transactions, so every service's transactional judgment is serialized on
// the same connection and no batch is ever half written.
//
// Devices and sessions form the registration layer. A device registers with a
// client-supplied id; a session belongs to exactly one registered device and
// is addressed by its own client-supplied id. Registration and session
// creation are idempotent re-posts: the first call creates, an identical
// repeat does not. A session id already owned by another device is a
// conflict, never silently re-homed. Deletes are owner-scoped and hard: a
// repeat delete, another device, and a cross-device path all miss with 404,
// after which the id is free to be created again.
//
// Attachments are resumable chunked uploads owned by the registered device
// that created them. Creation pins the declared total size, chunk size and
// SHA-256 digest; chunks land in any order and are stored durably as they
// arrive, so an interrupted upload resumes after a restart with its
// idempotency and conflict decisions intact. Finishing concatenates the
// chunks, verifies the digest and seals the upload; a sealed upload is
// immutable and rejects every further chunk write. Finished content is
// addressed by digest, so a second attachment with the same digest and size
// reuses the stored bytes instead of copying them. The creator may grant
// other registered devices read-only access per attachment; every
// (attachment, device) pair starts unauthorized, grants and revokes commit in
// the same serialized way, and access never widens the write paths. Deletes
// are owner-scoped and hard: the record, its chunks and its grants vanish in
// one serialized transaction, a repeat delete misses with 404, the id is free
// to be created again, and the shared content bytes are reclaimed once the
// last completed attachment referencing them is gone.
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

// ErrDeviceNotFound reports that an operation targets a device id that was
// never registered. Services map it to 404; nothing is written.
var ErrDeviceNotFound = errors.New("device not found")

// ErrPermissionDenied reports that a device's access to a document has been
// revoked. Services map it to 403; nothing is written and no document content
// is exposed. It is a shared verdict produced by the permission service and
// consulted by every service that enforces the gate inside a transaction.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// ErrSessionConflict reports that a session id already belongs to a different
// device. The session keeps its original owner; nothing is written. Services
// map it to 409.
type ErrSessionConflict struct {
	ID string
}

func (e *ErrSessionConflict) Error() string {
	return fmt.Sprintf("session %q belongs to another device", e.ID)
}

// ErrSessionNotFound reports that no live session matches the (device,
// session) pair: the session was never created, was already deleted, or
// belongs to another device. Services map it to 404.
var ErrSessionNotFound = errors.New("session not found")

// DBTX is the subset of *sql.DB and *sql.Tx the services use for their
// serialized work, so judgments made "in the same transaction" (for example a
// permission gate followed by the gated write) run on one concrete connection
// whether the caller holds a transaction or the handle itself.
type DBTX interface {
	Exec(query string, args ...any) (sql.Result, error)
	Query(query string, args ...any) (*sql.Rows, error)
	QueryRow(query string, args ...any) *sql.Row
}

// Store is the durable kernel: one SQLite database handle together with the
// device, session and attachment data it owns.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path. The empty path
// opens an in-memory database useful for tests.
func Open(path string) (*Store, error) {
	if path == "" {
		// With a single pooled connection this is a private, per-instance
		// in-memory database (useful for tests).
		path = "file::memory:"
	}
	// _txlock=immediate makes writers acquire the write lock at BEGIN, so
	// concurrent batches serialize without SQLITE_BUSY deadlocks.
	dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// One connection avoids cross-connection locking surprises; writes are
	// serialized by the immediate transaction anyway, and SQLite concurrency
	// for readers does not help correctness here. It also keeps every
	// service's transaction serialized on the same connection.
	db.SetMaxOpenConns(1)
	s := &Store{db: db}
	if err := s.init(); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

// DB returns the underlying handle. The business services use it to open the
// serialized transactions their judgments run in; callers outside the
// internal packages never need it.
func (s *Store) DB() *sql.DB { return s.db }

// Close releases the database handle.
func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) init() error {
	_, err := s.db.Exec(`
CREATE TABLE IF NOT EXISTS devices (
	id TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS sessions (
	id        TEXT NOT NULL PRIMARY KEY,
	device_id TEXT NOT NULL REFERENCES devices(id)
);
CREATE INDEX IF NOT EXISTS sessions_device_idx
	ON sessions(device_id);
CREATE TABLE IF NOT EXISTS attachments (
	id          TEXT NOT NULL PRIMARY KEY,
	device_id   TEXT NOT NULL REFERENCES devices(id),
	total_bytes INTEGER NOT NULL,
	chunk_size  INTEGER NOT NULL,
	sha256      TEXT NOT NULL,
	complete    INTEGER NOT NULL DEFAULT 0,
	reused      INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS attachment_chunks (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	idx           INTEGER NOT NULL,
	data          BLOB NOT NULL,
	PRIMARY KEY (attachment_id, idx)
);
CREATE TABLE IF NOT EXISTS attachment_contents (
	sha256 TEXT NOT NULL PRIMARY KEY,
	size   INTEGER NOT NULL,
	data   BLOB NOT NULL
);
CREATE TABLE IF NOT EXISTS attachment_access (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	device_id     TEXT NOT NULL,
	authorized    INTEGER NOT NULL,
	PRIMARY KEY (attachment_id, device_id)
);
`)
	return err
}

// RegisterDevice registers a device by client-supplied id. The first call for
// an id creates it and reports created=true; repeating the registration is
// idempotent (created=false). Device identity never changes.
func (s *Store) RegisterDevice(deviceID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	created, err = RegisterDeviceTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	return created, tx.Commit()
}

// RegisterDeviceTx is RegisterDevice against an existing transaction, so the
// services can resolve the registration layer as the first step of a larger
// serialized transaction (their permission/content gates then share it).
func RegisterDeviceTx(q DBTX, deviceID string) (created bool, err error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	if !exists {
		if _, err := q.Exec(`INSERT INTO devices (id) VALUES (?)`, deviceID); err != nil {
			return false, err
		}
		return true, nil
	}
	return false, nil
}

// DeviceExistsTx reports whether deviceID is registered, evaluated inside q so
// a service's gate runs on the same transaction as the work it guards.
func DeviceExistsTx(q DBTX, deviceID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// CreateSession creates a session owned by deviceID with a client-supplied id.
//
//   - An unknown device yields ErrDeviceNotFound; nothing is written.
//   - A session id already owned by another device yields *ErrSessionConflict;
//     nothing is written and the owner is unchanged.
//   - Re-posting the same (device, session) pair is idempotent: created=false.
//
// A deleted session is gone for good, so its id can be registered again as a
// brand-new session (created=true). The lookup, owner check and insert run in
// one serialized transaction, so concurrent creates of the same session id
// cannot both create it.
func (s *Store) CreateSession(deviceID, sessionID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO sessions (id, device_id) VALUES (?, ?)`,
			sessionID, deviceID,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID {
		return false, &ErrSessionConflict{ID: sessionID}
	}
	return false, tx.Commit()
}

// DeleteSession removes the live session matching the (deviceID, sessionID)
// pair. Any miss — the session does not exist, was already deleted, or belongs
// to another device — returns ErrSessionNotFound and changes nothing. The
// check and the delete run in one transaction, so a concurrent create cannot
// interleave and a repeat delete still misses; the removal is committed to
// disk before the call returns.
func (s *Store) DeleteSession(deviceID, sessionID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrSessionNotFound
	case err != nil:
		return err
	}
	if owner != deviceID {
		return ErrSessionNotFound
	}

	if _, err := tx.Exec(
		`DELETE FROM sessions WHERE id = ? AND device_id = ?`,
		sessionID, deviceID,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// SessionExists reports whether a live session with sessionID exists.
// Ownership is intentionally not part of this check: session-scoped reads only
// require that the session currently exists.
func (s *Store) SessionExists(sessionID string) (bool, error) {
	var exists bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM sessions WHERE id = ?)`, sessionID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// SessionDevice returns the id of the device that owns the live session
// sessionID. A session that was never created or was deleted yields
// ErrSessionNotFound.
func (s *Store) SessionDevice(sessionID string) (string, error) {
	var deviceID string
	err := s.db.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&deviceID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", ErrSessionNotFound
	case err != nil:
		return "", err
	default:
		return deviceID, nil
	}
}

// JSONEqual reports whether two payloads are equal after JSON decoding, so
// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal. It is shared
// verbatim by the change event and CRDT services' idempotency judgments.
func JSONEqual(a, b json.RawMessage) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return deepEqual(va, vb)
}

func deepEqual(a, b any) bool {
	switch av := a.(type) {
	case nil:
		return b == nil
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			w, exists := bv[k]
			if !exists || !deepEqual(v, w) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

// Package app is the composition root: it opens the one shared database and
// constructs the three independently reusable internal services — the change
// event service, the permission service and the CRDT state service — wiring
// them together only through their internal interfaces.
//
// The services share one SQLite connection (the kernel opens a single
// pooled connection with immediate transactions), so a change commit, a CRDT
// submission or compaction, and a permission change are serialized on the
// same connection and leave no half-written batch. The change event and CRDT
// services take their registration-and-authorization verdict from the
// permission service inside their own transactions (events.Gate / crdt.Gate),
// and the permission service fans a committed revoke out to their
// subscription registries through authz.RevokeSink. No service reaches into
// another service's tables or fields.
//
// App is the single object the entry and HTTP layers use. It promotes each
// service's input/output boundary as its methods while hiding the wiring; it
// adds no authentication and exposes no endpoint of its own.
package app

import (
	"context"
	"encoding/json"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/authz"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// App composes the durable kernel and the three internal services over one
// shared database connection.
type App struct {
	*store.Store

	events *events.Service
	crdt   *crdt.Service

	// Authz is the permission service. It is exposed so the HTTP layer can
	// grant/revoke and read authorization directly; the other services reach
	// it through their gates rather than this field.
	Authz *authz.Service
}

// Open opens (creating if needed) the SQLite database at path and constructs
// every internal service over it. The empty path opens a private in-memory
// database useful for tests. A construction failure closes the kernel and
// leaves nothing behind.
func Open(path string) (*App, error) {
	kernel, err := store.Open(path)
	if err != nil {
		return nil, err
	}

	// The permission service is built first: its gate is a constructor
	// dependency of the change event and CRDT services.
	permissions, err := authz.New(kernel)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	eventService, err := events.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	crdtService, err := crdt.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}

	// A committed revoke ends the affected live subscriptions in both
	// push channels. The dependency is an interface, registered once here, so
	// the permission service never names either subscriber concretely.
	permissions.AddRevokeSink(eventsRevokeSink{eventService})
	permissions.AddRevokeSink(crdtService)

	return &App{
		Store:  kernel,
		events: eventService,
		crdt:   crdtService,
		Authz:  permissions,
	}, nil
}

// eventsRevokeSink adapts the change event service's revoke hook to the
// permission service's RevokeSink interface.
type eventsRevokeSink struct{ e *events.Service }

func (s eventsRevokeSink) PermissionRevoked(documentID, deviceID string) {
	s.e.SignalRevoked(documentID, deviceID)
}

// Events returns the change event service.
func (a *App) Events() *events.Service { return a.events }

// CRDT returns the CRDT state service.
func (a *App) CRDT() *crdt.Service { return a.crdt }

// ---- Change event service boundary (promoted so the entry layer has one
// object; each method delegates verbatim to the events service). ----

// InterruptWaits wakes every parked long poll and every live change-log and
// CRDT subscription without closing the database, so an orderly shutdown
// drains waiting connections (long polls answer 503; subscriptions finish
// with the going-away close) instead of holding the drain hostage.
func (a *App) InterruptWaits() {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
}

// Closing reports whether shutdown has begun, covering both push channels.
func (a *App) Closing() bool {
	return a.events.Closing() || a.crdt.Closing()
}

// Close interrupts the in-memory observers, waits for every subscription
// handler to unregister and then releases the shared database handle.
func (a *App) Close() error {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
	a.events.WaitDrained()
	a.crdt.WaitDrained()
	return a.Store.Close()
}

// PostChanges delegates to the change event service.
func (a *App) PostChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.PostChanges(documentID, changes)
}

// ReplayChanges delegates to the change event service.
func (a *App) ReplayChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.ReplayChanges(documentID, changes)
}

// MergeChange delegates to the change event service.
func (a *App) MergeChange(documentID string, baseCursor int64, c events.Change) (events.MergeResult, error) {
	return a.events.MergeChange(documentID, baseCursor, c)
}

// PutSnapshot delegates to the change event service.
func (a *App) PutSnapshot(documentID string, cursor int64, state json.RawMessage) (bool, error) {
	return a.events.PutSnapshot(documentID, cursor, state)
}

// GetSnapshot delegates to the change event service.
func (a *App) GetSnapshot(documentID string, cursor int64) (json.RawMessage, error) {
	return a.events.GetSnapshot(documentID, cursor)
}

// ExportSnapshots delegates to the change event service. A nil to means the
// interval has no upper bound.
func (a *App) ExportSnapshots(documentID string, from int64, to *int64) ([]events.ExportedSnapshot, error) {
	return a.events.ExportSnapshots(documentID, from, to)
}

// RestoreSnapshot delegates to the change event service.
func (a *App) RestoreSnapshot(documentID, deviceID, changeID string, snapshotCursor int64) (events.RestoreResult, error) {
	return a.events.RestoreSnapshot(documentID, deviceID, changeID, snapshotCursor)
}

// ListChanges delegates to the change event service.
func (a *App) ListChanges(documentID string, after, limit int64) ([]events.ListedChange, int64, error) {
	return a.events.ListChanges(documentID, after, limit)
}

// WaitForChanges delegates to the change event service.
func (a *App) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) ([]events.ListedChange, int64, bool, error) {
	return a.events.WaitForChanges(ctx, documentID, after, limit, wait)
}

// DocumentExists delegates to the change event service.
func (a *App) DocumentExists(documentID string) (bool, error) {
	return a.events.DocumentExists(documentID)
}

// AddSubscription delegates to the change event service.
func (a *App) AddSubscription(documentID, deviceID string) (<-chan struct{}, <-chan struct{}, func()) {
	return a.events.AddSubscription(documentID, deviceID)
}

// ---- Permission service boundary. ----

// SetDocumentPermission delegates to the permission service.
func (a *App) SetDocumentPermission(documentID, deviceID string, authorized bool) (bool, error) {
	return a.Authz.SetDocumentPermission(documentID, deviceID, authorized)
}

// DocumentAuthorized delegates to the permission service.
func (a *App) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	return a.Authz.DocumentAuthorized(documentID, deviceID)
}

// ---- CRDT state service boundary. ----

// SubmitCRDTOps delegates to the CRDT state service.
func (a *App) SubmitCRDTOps(documentID, declaredType string, ops []crdt.Op) ([]crdt.Result, error) {
	return a.crdt.SubmitOps(documentID, declaredType, ops)
}

// GetCRDTState delegates to the CRDT state service.
func (a *App) GetCRDTState(documentID string) (crdt.State, error) {
